    await user.type(password, 'secret{Enter}');
    expect(args.onSubmit).toHaveBeenCalledTimes(1);
    const submitted = args.onSubmit.mock.calls[0][0];
    expect(submitted.inputs.email.value).toBe('player@courthive.com');
